import Foundation

/// The bundled national real-estate exam question bank.
///
/// All content is general / national in scope (clearly NOT state-specific law) and
/// authored for study. Each question has exactly four options, one correct answer,
/// and a one–three sentence explanation. IDs are stable and used as `QuestionStat` keys.
enum QuestionBank {

    /// Convenience builder keeping the literal table compact and readable.
    private static func q(_ id: Int, _ topic: Topic, _ prompt: String,
                          _ options: [String], _ correct: Int, _ explanation: String) -> Question {
        Question(id: id, topic: topic, prompt: prompt, options: options,
                 correctIndex: correct, explanation: explanation)
    }

    /// The full bank. ~120 questions, evenly distributed across the ten topics.
    static let all: [Question] = ownership + agency + valuation + financing + contracts
        + titleTransfer + disclosures + leasing + math + practice

    /// Questions for a single topic.
    static func forTopic(_ topic: Topic) -> [Question] {
        all.filter { $0.topic == topic }
    }

    /// Lookup by id (guarded).
    static func byId(_ id: Int) -> Question? {
        all.first { $0.id == id }
    }

    // MARK: - Property Ownership & Land Use (1–12)

    private static let ownership: [Question] = [
        q(1, .ownership, "Which estate provides the most complete form of ownership, lasting indefinitely and freely inheritable?",
          ["Fee simple absolute", "Life estate", "Leasehold estate", "Estate for years"], 0,
          "A fee simple absolute is the highest, most complete estate — of potentially infinite duration and fully inheritable."),
        q(2, .ownership, "A life estate is measured by:",
          ["A fixed term of 99 years", "The lifetime of a named person", "The life of the property", "The mortgage term"], 1,
          "A life estate lasts only for the lifetime of the measuring life; when that person dies it passes to the remainderman or reverts to the grantor."),
        q(3, .ownership, "The right of a government to take private property for public use upon payment of just compensation is called:",
          ["Escheat", "Eminent domain", "Police power", "Estoppel"], 1,
          "Eminent domain (exercised through condemnation) lets government take private property for public use with just compensation."),
        q(4, .ownership, "Which is an example of the government's police power rather than eminent domain?",
          ["Building a highway through a parcel", "Zoning ordinances limiting use", "Paying an owner for a taking", "Property reverting to the state"], 1,
          "Police power (zoning, building codes, health/safety rules) regulates use without compensation; eminent domain takes title with compensation."),
        q(5, .ownership, "An encroachment is best described as:",
          ["A lien recorded against title", "An unauthorized physical intrusion onto another's land", "A right to cross another's land", "A deed restriction"], 1,
          "An encroachment is a physical intrusion — like a fence or roofline crossing the boundary — onto a neighbor's property."),
        q(6, .ownership, "An easement that benefits an adjoining parcel and transfers with the land is a(n):",
          ["Easement in gross", "Easement appurtenant", "License", "Encroachment"], 1,
          "An easement appurtenant runs with the land, benefiting a dominant tenement and burdening a servient tenement; it passes with ownership."),
        q(7, .ownership, "Two people own property as joint tenants. A key feature of this ownership is:",
          ["Unequal shares are allowed", "The right of survivorship", "Ownership passes by will", "Each can mortgage the whole"], 1,
          "Joint tenancy carries the right of survivorship — a deceased joint tenant's interest passes automatically to the survivors, not by will."),
        q(8, .ownership, "The four unities required to create a joint tenancy are time, title, interest, and:",
          ["Possession", "Profit", "Priority", "Partition"], 0,
          "Joint tenancy requires the four unities — time, title, interest, and possession (PITT)."),
        q(9, .ownership, "Property owned by a married couple with right of survivorship and protection from individual creditors is often held as:",
          ["Tenancy in common", "Tenancy by the entirety", "Severalty", "A partnership"], 1,
          "Tenancy by the entirety is a form of co-ownership reserved for married couples, featuring survivorship and creditor protections."),
        q(10, .ownership, "Ownership of real property by one individual or entity alone is called ownership in:",
          ["Severalty", "Common", "Survivorship", "Trust"], 0,
          "Ownership in severalty means a sole owner — one person or entity holds the entire estate."),
        q(11, .ownership, "Which of the following is generally considered real property rather than personal property?",
          ["A free-standing refrigerator", "A built-in dishwasher attached to cabinetry", "Patio furniture", "A potted plant"], 1,
          "A built-in appliance permanently attached to the structure is a fixture, and fixtures are part of the real property."),
        q(12, .ownership, "A test used to decide whether an item is a fixture includes the method of attachment, adaptation to the real estate, and:",
          ["The item's resale value", "The intention of the party who installed it", "The age of the item", "Whether it is insured"], 1,
          "Courts weigh attachment, adaptation, and — most importantly — the intention of the parties when classifying an item as a fixture (the IRMA/MARIA tests)."),
    ]

