        q(22, .agency, "Commingling refers to a broker improperly:",
          ["Representing two buyers", "Mixing client trust funds with the broker's own funds", "Splitting a commission", "Advertising another broker's listing"], 1,
          "Commingling is mixing clients' trust/escrow money with the broker's personal or business funds — a serious violation; converting it to personal use is conversion."),
        q(23, .agency, "An agency relationship is most commonly terminated by all of the following EXCEPT:",
