    // MARK: - Leasing & Property Management (85–96)

    private static let leasing: [Question] = [
        q(85, .leasing, "A lease in which the tenant pays a fixed rent and the landlord pays the property's operating expenses is a:",
          ["Net lease", "Gross lease", "Percentage lease", "Ground lease"], 1,
          "In a gross lease the tenant pays flat rent and the landlord covers taxes, insurance, and maintenance."),
        q(86, .leasing, "A retail lease where rent is partly based on the tenant's sales volume is a:",
          ["Gross lease", "Net lease", "Percentage lease", "Index lease"], 2,
          "A percentage lease, common in retail, sets rent as a base amount plus a percentage of the tenant's gross sales."),
        q(87, .leasing, "A leasehold estate that continues for a definite period and ends without notice is an:",
          ["Estate at will", "Estate for years", "Periodic estate", "Estate at sufferance"], 1,
          "An estate (tenancy) for years runs for a fixed, definite term and terminates automatically at the end without further notice."),
        q(88, .leasing, "A month-to-month tenancy that automatically renews until proper notice is given is a(n):",
          ["Estate for years", "Periodic estate", "Estate at sufferance", "Estate at will"], 1,
          "A periodic estate (e.g., month-to-month) renews automatically for successive periods until either party gives the required notice."),
        q(89, .leasing, "A tenant who remains in possession after the lease expires, without the landlord's consent, holds an:",
          ["Estate for years", "Estate at sufferance", "Periodic estate", "Estate at will"], 1,
          "A holdover tenant without permission holds an estate at sufferance — the lowest leasehold, where possession continues without right."),
        q(90, .leasing, "The covenant of quiet enjoyment in a lease guarantees the tenant:",
          ["A soundproof unit", "Possession without interference from the landlord or superior claims", "Free utilities", "A rent reduction"], 1,
          "Quiet enjoyment assures the tenant the right to possess and use the premises without wrongful interference by the landlord or those with paramount title."),
        q(91, .leasing, "When a tenant transfers the entire remaining lease term to another, it is a(n):",
          ["Sublease", "Assignment", "Novation", "Eviction"], 1,
          "An assignment transfers the tenant's entire remaining interest; a sublease transfers only part, with the original tenant retaining a reversion."),
        q(92, .leasing, "Constructive eviction occurs when:",
          ["The landlord changes the locks legally", "The premises become uninhabitable due to the landlord's neglect, forcing the tenant out", "The tenant stops paying rent", "The lease expires"], 1,
          "Constructive eviction happens when a landlord's failure to maintain habitability so disrupts the tenant that they must leave; the tenant may then end the lease."),
        q(93, .leasing, "Security deposit rules typically require a landlord to:",
          ["Keep the deposit regardless of condition", "Return it (less lawful deductions) within a statutory period", "Use it as last month's rent always", "Never account for it"], 1,
          "Most state landlord-tenant laws require returning the security deposit, minus lawful deductions for damage/unpaid rent, within a set time and with an itemized statement."),
        q(94, .leasing, "A property manager's primary fiduciary obligation is to:",
          ["The tenants", "The owner/principal", "The listing broker", "The lender"], 1,
          "A property manager is the owner's agent and owes fiduciary duties — including maximizing return and protecting the asset — to the owner/principal."),
        q(95, .leasing, "In property management, a management agreement most resembles which kind of agency?",
          ["Special agency", "General agency", "Universal agency", "No agency"], 1,
          "A property manager is typically a general agent, authorized to handle a range of ongoing tasks (leasing, collecting rent, maintenance) for the owner."),
        q(96, .leasing, "The actual taking of possession by a landlord through a court process after a tenant defaults is:",
          ["Constructive eviction", "Actual eviction (e.g., unlawful detainer)", "Surrender", "Abandonment"], 1,
          "Actual eviction is the landlord's legal process (such as an unlawful detainer suit) to regain possession from a defaulting tenant."),
    ]

    // MARK: - Real Estate Math (97–108)

    private static let math: [Question] = [
        q(97, .math, "A home sells for $250,000 at a 6% total commission. What is the total commission?",
          ["$1,500", "$15,000", "$25,000", "$150,000"], 1,
          "$250,000 × 0.06 = $15,000 total commission."),
        q(98, .math, "From a $15,000 commission split 50/50 between listing and selling brokerages, then 60% to the selling agent, the selling agent earns:",
          ["$3,000", "$4,500", "$7,500", "$9,000"], 1,
          "$15,000 × 50% = $7,500 to the selling side; $7,500 × 60% = $4,500 to the selling agent."),
        q(99, .math, "A lot is 100 feet by 150 feet. How many square feet is it?",
          ["1,500", "15,000", "150,000", "250"], 1,
          "Area = 100 ft × 150 ft = 15,000 square feet."),
        q(100, .math, "One acre equals how many square feet?",
          ["5,280", "10,000", "43,560", "640"], 2,
          "One acre = 43,560 square feet; a section (one square mile) is 640 acres."),
        q(101, .math, "A property is purchased for $180,000 and sold for $216,000. What is the percent of profit on cost?",
          ["10%", "16%", "20%", "36%"], 2,
          "Profit = $36,000; $36,000 ÷ $180,000 = 0.20 = 20% profit on cost."),
        q(102, .math, "Annual property taxes are $3,650. Using a 365-day year, the daily tax (for proration) is:",
          ["$1.00", "$10.00", "$3.65", "$36.50"], 1,
          "$3,650 ÷ 365 days = $10.00 per day, the per-diem figure used to prorate taxes at closing."),
        q(103, .math, "A loan of $200,000 at 6% annual interest. What is the first month's interest (interest-only)?",
          ["$120", "$1,000", "$1,200", "$12,000"], 1,
          "$200,000 × 0.06 = $12,000 per year ÷ 12 = $1,000 for the first month."),
        q(104, .math, "A buyer puts 20% down on a $300,000 home. What is the loan amount?",
          ["$60,000", "$240,000", "$280,000", "$200,000"], 1,
          "Down payment = $300,000 × 0.20 = $60,000; loan = $300,000 − $60,000 = $240,000."),
        q(105, .math, "If a home's value increased 25% to $400,000, what was the original value?",
          ["$300,000", "$320,000", "$375,000", "$350,000"], 1,
          "Original × 1.25 = $400,000, so original = $400,000 ÷ 1.25 = $320,000."),
        q(106, .math, "A seller wants to net $190,000 after paying a 5% commission. The minimum sale price (ignoring other costs) is about:",
          ["$199,500", "$200,000", "$209,000", "$195,000"], 1,
          "Price × (1 − 0.05) = $190,000, so Price = $190,000 ÷ 0.95 = $200,000."),
        q(107, .math, "A property assessed at $250,000 with a tax rate of 1.2% owes annual taxes of:",
          ["$300", "$3,000", "$30,000", "$2,500"], 1,
          "$250,000 × 0.012 = $3,000 in annual property taxes."),
        q(108, .math, "Taxes of $2,400/year are prorated to the buyer for the last 3 months of the year (seller owes Jan–Sep). Using months, the seller's share is:",
          ["$600", "$1,200", "$1,800", "$2,400"], 2,
          "$2,400 ÷ 12 = $200/month; the seller owns 9 months (Jan–Sep): 9 × $200 = $1,800."),
    ]

    // MARK: - Practice of Real Estate (109–120)

    private static let practice: [Question] = [
        q(109, .practice, "Funds a broker holds on behalf of clients (e.g., earnest money) must be kept in a:",
          ["Personal checking account", "Trust (escrow) account", "Business operating account", "Money market fund of the broker"], 1,
          "Client funds must be held in a separate trust/escrow account, never commingled with the broker's own funds."),
        q(110, .practice, "Two competing brokerages agreeing to charge the same commission rate is:",
          ["Legal price matching", "Illegal price fixing (antitrust)", "A net listing", "A buyer agency agreement"], 1,
          "Agreeing to fix commission rates among competitors violates antitrust law; commissions must be independently negotiable."),
        q(111, .practice, "Competitors dividing territories or customers among themselves is an antitrust violation known as:",
          ["Steering", "Market allocation", "Blockbusting", "Tie-in arrangement"], 1,
          "Market (customer or territory) allocation among competitors is a per se antitrust violation."),
        q(112, .practice, "Advertising a property at an attractive price that the broker has no intention of selling, to lure buyers, is:",
          ["Puffing", "A bait-and-switch / false advertising", "A net listing", "Steering"], 1,
          "Bait-and-switch advertising is a deceptive, prohibited practice; advertising must be truthful and not misleading."),
        q(113, .practice, "An independent contractor relationship between a broker and salesperson typically means the salesperson:",
          ["Is a W-2 employee with set hours", "Controls their own schedule and is paid by commission", "Receives company benefits and hourly pay", "Cannot be supervised at all"], 1,
          "Most agents are independent contractors paid by commission who control their schedule, though the broker still supervises compliance and remains responsible for their licensed acts."),
        q(114, .practice, "A salesperson's license is generally held and supervised by:",
          ["The state directly", "Their sponsoring/employing broker", "The MLS", "The local board only"], 1,
          "A salesperson must work under and be supervised by a sponsoring broker, who is responsible for the salesperson's licensed activities."),
        q(115, .practice, "Performing licensed real estate activity for compensation without a license generally results in:",
          ["A warning only", "Penalties and inability to collect a commission", "Automatic licensure", "No consequence"], 1,
          "Unlicensed practice is unlawful; violators face penalties and courts will not enforce a commission claim by an unlicensed person."),
        q(116, .practice, "The Multiple Listing Service (MLS) primarily functions to:",
          ["Set commission rates", "Let member brokers share listings and offers of cooperation/compensation", "License agents", "Appraise properties"], 1,
          "The MLS is a cooperative database where member brokers share listings and offers of cooperation/compensation; it does not set commissions."),
        q(117, .practice, "Designated (appointed) agency is when:",
          ["No one represents the buyer", "A broker appoints different agents in the firm to represent buyer and seller separately", "Two firms merge", "The seller represents themselves"], 1,
          "In designated agency, the managing broker appoints separate licensees within the same firm to represent the buyer and the seller, reducing dual-agency conflicts."),
        q(118, .practice, "A broker's duty to supervise includes responsibility for:",
          ["Only their own transactions", "The licensed activities and trust funds handled by their agents", "Nothing once licenses are issued", "Appraisals only"], 1,
          "The supervising broker is responsible for the licensed conduct of affiliated agents and for proper handling of trust funds and records."),
        q(119, .practice, "Continuing education requirements for license renewal exist primarily to:",
          ["Increase commissions", "Keep licensees current on law and practice", "Replace the original exam", "Limit the number of agents"], 1,
          "Continuing education ensures licensees stay current with changing laws, regulations, and ethical practice as a condition of renewal."),
        q(120, .practice, "An associate broker differs from a salesperson in that the associate broker:",
          ["Cannot list property", "Has met broker-level qualifications but works under another broker", "Owns the firm by law", "Needs no license"], 1,
          "An associate broker has earned a broker's license but chooses to work under a managing/principal broker rather than operate independently."),
    ]
}
